import { Body, Controller, Logger, Post, Req } from '@nestjs/common';
import type { RawBodyRequest } from '@nestjs/common';
import type { Request } from 'express';
import { VerifyStripeWebhookUseCase } from '../../application/use-cases/verify-stripe-webhook.use-case';

@Controller('payments/webhook')
export class PaymentWebhookController {
  private readonly logger = new Logger(PaymentWebhookController.name);

  constructor(
    private readonly verifyStripeWebhookUseCase: VerifyStripeWebhookUseCase,
  ) {}

  @Post('stripe')
  async handleStripeWebhook(
    @Req() request: RawBodyRequest<Request>,
    @Body() body: Record<string, unknown>,
  ): Promise<{ received: boolean }> {
    const stripeSignatureHeader = request.headers['stripe-signature'];
    const signature = Array.isArray(stripeSignatureHeader)
      ? stripeSignatureHeader[0]
      : stripeSignatureHeader;

    if (!signature) {
      this.logger.warn('Missing stripe-signature header');
      return { received: false };
    }

    const rawBody = request.rawBody ?? Buffer.from(JSON.stringify(body));
    const verification = this.verifyStripeWebhookUseCase.execute(
      rawBody,
      signature,
    );

    if (!verification.verified) {
      this.logger.warn(
        `Webhook signature verification failed: ${verification.error}`,
      );
      return { received: false };
    }

    const eventType = typeof body.type === 'string' ? body.type : 'unknown';
    this.logger.log(`Stripe webhook received: ${eventType}`);

    return { received: true };
  }
}

import { Controller, Get, Param } from '@nestjs/common';
import {
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiTags,
} from '@nestjs/swagger';
import { ListUsersUseCase } from '../../application/use-cases/list-users.use-case';
import { GetUserByIdUseCase } from '../../application/use-cases/get-user-by-id.use-case';
import { UserDtoMapper } from '../../application/mappers/user-dto.mapper';
import { UserResponseDto } from '../../application/dto/user.response.dto';

@ApiTags('Users')
@Controller('users')
export class UserController {
  constructor(
    private readonly listUsersUseCase: ListUsersUseCase,
    private readonly getUserByIdUseCase: GetUserByIdUseCase,
  ) {}

  @Get()
  @ApiOperation({ summary: 'List all users' })
  @ApiOkResponse({ type: UserResponseDto, isArray: true })
  async list(): Promise<UserResponseDto[]> {
    const users = await this.listUsersUseCase.execute();
    return users.map(UserDtoMapper.toResponse);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get user by id' })
  @ApiParam({ name: 'id', example: '3b1f8c22-930f-4b6d-8ac4-d54c5988e6d3' })
  @ApiOkResponse({ type: UserResponseDto })
  async findById(@Param('id') id: string): Promise<UserResponseDto> {
    const user = await this.getUserByIdUseCase.execute(id);
    return UserDtoMapper.toResponse(user);
  }
}

